// a vector of the mean response real mu[N]; // the cumulative media effect after adstock real cum_effect; // the cumulative media effect after adstock, and then Hill transformation row_vector[num_media] cum_effects_hill[N]; row_vector[max_lag] lag_weights; for (nn in 1:N) { for (media in 1 : num_media) { for (lag in 1 : max_lag) { lag_weights[lag] <- pow(retain_rate[media], (lag - 1 - delay[media]) ^ 2); } cum_effect <- Adstock(X_media[nn, media], lag_weights); cum_effects_hill[nn, media] <- Hill(cum_effect, ec[media], slope[media]); } mu[nn] <- tau + dot_product(cum_effects_hill[nn], beta_medias) + dot_product(X_ctrl[nn], gamma_ctrl); } } model { retain_rate ~ beta(3,3); delay ~ uniform(0, max_lag - 1); slope ~ gamma(3, 1); ec ~ beta(2,2); tau ~ normal(0, 5); for (media_index in 1 : num_media) { beta_medias[media_index] ~ normal(0, 1); } for (ctrl_index in 1 : num_ctrl) { gamma_ctrl[ctrl_index] ~ normal(0,1); } noise_var ~ inv_gamma(0.05, 0.05 * 0.01); Y ~ normal(mu, sqrt(noise_var)); }
